steps.expression:
// Parameters.config was filled by the Parse Config step from the answer
// of the configuration Flow. Nothing here knows which environment it is.
var cfg = Parameters.config;

// Change the endpoint once, in the configuration Flow, and every Flow
// that reads it follows. That is the whole point of the indirection.
var url = $"{cfg.ratesUrl}/latest?base={Input.key}";

Logger.LogInformation($"the call would go to {url}, "
    + $"taking {cfg.pageSize} rows at a time");
return new LookupRequest() { key = url };
